AnimationStep *createAnimationSteps(Snake *snake, GameGrid *grid, int dx, int dy) {
    int currentFrame = 0;
    AnimationStep *steps = malloc(4 * sizeof(AnimationStep));
    for (int I = 0; I < 4; i++) {
        moveSnake(snake, dx, dy);
        if (isColliding(snake, grid)) {
            return NULL;
        }
        AnimationStep *step = createAnimationStep(snake, grid, currentFrame);
        steps[i] = *step;
