void renderFrame(SDL_Renderer *renderer, AnimationStep *step) {
    SDL_Surface *background = loadImage("background.png");
    SDL_Surface *snakeImage = loadImage("snake.png");
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
    SDL_RenderClear(renderer);
